fun publish(draft: Draft): Published {
    requireNotNull(draft.body) { "body required" }               // guard: caller input
    val repo = drafts.repo ?: return Published.draftOnly(draft)  // guard: state
    check(draft.readyAt <= clock.now()) { "not ready yet" }      // guard: state
    return repo.publish(draft)                                   // happy path stays flat
}
